import json

"""Deterministic criteria engine shared by the payer service (mock mode) and the
Snowflake stored procedures (the generator embeds this file in the SP body).

Rules (PRD 8.6):
- The LLM only extracts facts. Thresholds are applied here, never by a model.
- Three-valued logic: MET / NOT_MET / UNKNOWN.
- AUTO_APPROVE only when the tree is MET and every leaf that satisfies it has a
  verified citation. Anything uncertain becomes PEND. A NOT_MET tree becomes
  RECOMMEND_DENY only if a failing leaf is marked RECOMMEND_DENY; that outcome
  goes to a clinician and is never a denial by itself.

Keep this module standard-library only and free of double dollar signs so it can be
embedded in a Snowflake Python stored procedure.
"""

import re

MET, NOT_MET, UNKNOWN = "MET", "NOT_MET", "UNKNOWN"
AUTO_APPROVE, PEND, RECOMMEND_DENY = "AUTO_APPROVE", "PEND", "RECOMMEND_DENY"


def normalize_space(text):
    return re.sub(r"\s+", " ", text or "").strip()


def verify_quote(quote, doc_text):
    """A citation is valid only if the quote is an exact substring of the
    document (whitespace-normalized). Paraphrases fail on purpose."""
    if not quote or not doc_text:
        return False
    return normalize_space(quote) in normalize_space(doc_text)


def _to_bool(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        v = value.strip().lower()
        if v in ("true", "yes", "y", "1"):
            return True
        if v in ("false", "no", "n", "0"):
            return False
    if isinstance(value, (int, float)):
        return bool(value)
    return None


def _to_num(value):
    if isinstance(value, bool):
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def compare(value, operator, threshold):
    """Return MET / NOT_MET / UNKNOWN for one leaf."""
    if value is None or value == "":
        return UNKNOWN
    if isinstance(threshold, bool) or (isinstance(threshold, str) and threshold.lower() in ("true", "false")):
        left, right = _to_bool(value), _to_bool(threshold)
        if left is None or right is None:
            return UNKNOWN
        ok = left == right if operator == "=" else left != right
        return MET if ok else NOT_MET
    left, right = _to_num(value), _to_num(threshold)
    if left is None or right is None:
        if operator == "=":
            return MET if str(value).strip().lower() == str(threshold).strip().lower() else NOT_MET
        return UNKNOWN
    ops = {
        ">=": left >= right, ">": left > right, "<=": left <= right,
        "<": left < right, "=": left == right, "!=": left != right,
    }
    if operator not in ops:
        return UNKNOWN
    return MET if ops[operator] else NOT_MET


def _combine(node_type, statuses):
    if node_type == "AND":
        if NOT_MET in statuses:
            return NOT_MET
        return MET if statuses and all(s == MET for s in statuses) else UNKNOWN
    if node_type == "OR":
        if MET in statuses:
            return MET
        return NOT_MET if statuses and all(s == NOT_MET for s in statuses) else UNKNOWN
    raise ValueError("unknown node type " + str(node_type))


def evaluate(nodes, facts):
    """Evaluate a criteria tree.

    nodes: list of dicts with node_id, parent_node_id, node_type (AND|OR|LEAF),
           label, fact_name, operator, threshold, on_not_met, policy_section_id,
           sort_order.
    facts: {fact_name: {"value": ..., "quote": str|None, "doc_id": str|None,
            "verified": bool, "origin": "auto"|"override"|"manual"}}
    """
    by_id = {n["node_id"]: dict(n) for n in nodes}
    children = {}
    roots = []
    for n in sorted(by_id.values(), key=lambda x: (x.get("sort_order") or 0, x["node_id"])):
        parent = n.get("parent_node_id")
        if parent:
            children.setdefault(parent, []).append(n["node_id"])
        else:
            roots.append(n["node_id"])
    if len(roots) != 1:
        raise ValueError("criteria tree must have exactly one root, found %d" % len(roots))

    results = {}

    def visit(node_id, depth):
        node = by_id[node_id]
        if node["node_type"] == "LEAF":
            fact = facts.get(node.get("fact_name")) or {}
            status = compare(fact.get("value"), node.get("operator"), node.get("threshold"))
            results[node_id] = dict(
                node, depth=depth, status=status, value=fact.get("value"),
                quote=fact.get("quote"), doc_id=fact.get("doc_id"),
                citation_verified=bool(fact.get("verified")), origin=fact.get("origin"),
            )
            return status
        statuses = [visit(c, depth + 1) for c in children.get(node_id, [])]
        status = _combine(node["node_type"], statuses)
        results[node_id] = dict(node, depth=depth, status=status)
        return status

    root_status = visit(roots[0], 0)

    def satisfying_leaves(node_id):
        r = results[node_id]
        if r["node_type"] == "LEAF":
            return [node_id]
        kids = children.get(node_id, [])
        if r["node_type"] == "OR":
            for c in kids:
                if results[c]["status"] == MET:
                    return satisfying_leaves(c)
            return []
        out = []
        for c in kids:
            out.extend(satisfying_leaves(c))
        return out

    def failing_leaves(node_id):
        r = results[node_id]
        if r["node_type"] == "LEAF":
            return [node_id] if r["status"] == NOT_MET else []
        out = []
        for c in children.get(node_id, []):
            if results[c]["status"] == NOT_MET:
                out.extend(failing_leaves(c))
        return out

    leaves = [r for r in results.values() if r["node_type"] == "LEAF"]
    unknown = [r for r in leaves if r["status"] == UNKNOWN]
    missing_info = []
    unmet = []

    if root_status == MET:
        support = [results[i] for i in satisfying_leaves(roots[0])]
        unverified = [r for r in support if not r["citation_verified"]]
        if unverified:
            recommendation = PEND
            missing_info = [
                "Supporting documentation for: %s (section %s)" % (r["label"], r["policy_section_id"])
                for r in unverified
            ]
            reason = "Criteria appear to be met, but %d answer(s) lack a verifiable quote from the submitted records." % len(unverified)
        else:
            recommendation = AUTO_APPROVE
            reason = "All required criteria are met, each backed by a verified quote from the submitted records."
    elif root_status == UNKNOWN:
        recommendation = PEND
        missing_info = [
            "Documentation of: %s (section %s)" % (r["label"], r["policy_section_id"]) for r in unknown
        ]
        reason = "Some criteria could not be assessed from the submitted information."
    else:
        failing = [results[i] for i in failing_leaves(roots[0])]
        unmet = [
            "%s (section %s): documented value %s" % (r["label"], r["policy_section_id"], _fmt(r["value"]))
            for r in failing
        ]
        if any(r.get("on_not_met") == RECOMMEND_DENY for r in failing):
            recommendation = RECOMMEND_DENY
            reason = "The documented values do not meet the policy criteria. A clinician must review before any denial."
        else:
            recommendation = PEND
            missing_info = [
                "Documentation that would satisfy: %s (section %s)" % (r["label"], r["policy_section_id"])
                for r in failing
            ]
            reason = "Criteria are not yet met; additional documentation may satisfy them."

    ordered = [results[n["node_id"]] for n in sorted(by_id.values(), key=lambda x: (x.get("sort_order") or 0))]
    return {
        "recommendation": recommendation,
        "root_status": root_status,
        "reason_text": reason,
        "missing_info": missing_info,
        "unmet": unmet,
        "criteria": [_public(r) for r in ordered],
    }


def _fmt(value):
    if value is None:
        return "not documented"
    if isinstance(value, bool):
        return "yes" if value else "no"
    return str(value)


def _public(r):
    keys = ("node_id", "parent_node_id", "node_type", "label", "fact_name", "operator", "threshold",
            "on_not_met", "policy_section_id", "depth", "status", "value", "quote", "doc_id",
            "citation_verified", "origin")
    return {k: r.get(k) for k in keys}


# Shared helpers embedded into the Python stored procedures by build_sql.py.
import json as _json


def q(session, sql, params=None):
    rows = session.sql(sql, params=params or []).collect()
    out = []
    for r in rows:
        d = {}
        for k, v in r.as_dict().items():
            if isinstance(v, str) and v[:1] in ("{", "["):
                try:
                    v = _json.loads(v)
                except ValueError:
                    pass
            d[k.lower()] = v
        out.append(d)
    return out


def scalar(session, sql, params=None):
    return session.sql(sql, params=params or []).collect()[0][0]


def _iso(v):
    return v.isoformat() if hasattr(v, "isoformat") else v


def load_nodes(session, policy_doc_id):
    rows = q(session,
             "SELECT node_id, parent_node_id, node_type, label, fact_name, operator, threshold, on_not_met, "
             "policy_section_id, sort_order FROM PAYER.POLICY_CRITERIA WHERE policy_doc_id = ? ORDER BY sort_order",
             [policy_doc_id])
    for r in rows:
        t = r.get("threshold")
        if isinstance(t, str):
            try:
                r["threshold"] = _json.loads(t)
            except ValueError:
                pass
    return rows


def decide(session, pa_id, admin_ref, code, by, role, reason_text, request_text=None):
    approve = code in ("A1", "A6")
    auth = "AUTH-%s" % scalar(session, "SELECT PAYER.SEQ_AUTH.NEXTVAL") if approve else None
    session.sql(
        "INSERT INTO PAYER.DECISION (pa_id, review_action_code, auth_number, admin_ref_number, auth_period_start, "
        "auth_period_end, reason_text, request_text, decided_by, decider_role, ai_assisted) "
        "SELECT ?, ?, ?, ?, IFF(?, CURRENT_DATE(), NULL), IFF(?, DATEADD(day, 90, CURRENT_DATE()), NULL), ?, ?, ?, ?, TRUE",
        params=[pa_id, code, auth, admin_ref, approve, approve, reason_text, request_text, by, role]).collect()
    row = q(session, "SELECT * FROM PAYER.DECISION WHERE pa_id = ? ORDER BY decided_at DESC LIMIT 1", [pa_id])[0]
    return row


def result_of(pa, decision, result):
    return {
        "pa_id": pa["pa_id"], "claim_id": pa["claim_id"], "status": pa["status"],
        "recommendation": pa["recommendation"], "review_action": decision["review_action_code"],
        "auth_number": decision["auth_number"], "admin_ref": decision["admin_ref_number"],
        "period_start": _iso(decision["auth_period_start"]), "period_end": _iso(decision["auth_period_end"]),
        "reason_text": decision["reason_text"], "request_text": decision["request_text"],
        "missing_info": pa.get("missing_info") or [], "unmet": pa.get("unmet") or [],
        "criteria": (result or {}).get("criteria") or pa.get("criteria") or [],
        "sla_due_at": _iso(pa["sla_due_at"]), "decided_by": decision["decided_by"],
        "provider_org_npi": pa.get("provider_org_npi"), "patient_id": pa["patient_id"], "member_id": pa["member_id"],
    }


# Cortex structured extraction embedded into AI.SP_DTR_AUTOFILL and AI.SP_AI_REVIEW.
# The model only finds facts and copies a verbatim quote; thresholds are applied
# later by the criteria engine, and every quote is re-verified as a substring.
import json as _json
import re as _re

_SCHEMA = {
    "type": "object",
    "properties": {
        "answers": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "linkId": {"type": "string"},
                    "found": {"type": "boolean"},
                    "value": {"type": "string"},
                    "quote": {"type": "string"},
                    "doc_id": {"type": "string"},
                    "confidence": {"type": "string", "enum": ["High", "Medium", "Low"]},
                },
                "required": ["linkId", "found"],
            },
        }
    },
    "required": ["answers"],
}


def _sql_literal(obj):
    """Python -> Snowflake OBJECT/ARRAY constant (for response_format)."""
    if isinstance(obj, dict):
        return "{" + ", ".join("'%s': %s" % (k, _sql_literal(v)) for k, v in obj.items()) + "}"
    if isinstance(obj, list):
        return "[" + ", ".join(_sql_literal(v) for v in obj) + "]"
    if isinstance(obj, bool):
        return "TRUE" if obj else "FALSE"
    if isinstance(obj, (int, float)):
        return str(obj)
    return "'" + str(obj).replace("'", "''") + "'"


def _model(session):
    rows = session.sql("SELECT value FROM AI.APP_CONFIG WHERE key = 'LLM_MODEL'").collect()
    model = rows[0][0] if rows else "claude-haiku-5-5"
    if not _re.match(r"^[a-z0-9.\-]+$", model):
        raise ValueError("Invalid model name in AI.APP_CONFIG")
    return model


def _coerce(item_type, raw):
    if raw is None or raw == "":
        return None
    try:
        if item_type == "boolean":
            return str(raw).strip().lower() in ("true", "yes", "1")
        if item_type == "integer":
            return int(float(raw))
        if item_type == "decimal":
            return float(str(raw).replace("%", ""))
    except ValueError:
        return None
    return raw


def cortex_extract(session, items, notes):
    """items: [{linkId, text, type}]; notes: [{doc_id, title, encounter_date, text}].
    Returns {linkId: {value, quote, doc_id, confidence, method}} for found facts."""
    model = _model(session)
    notes_block = "\n\n".join(
        "<document doc_id=\"%s\" date=\"%s\" title=\"%s\">\n%s\n</document>" % (n["doc_id"], n.get("encounter_date"), n.get("title"), n["text"])
        for n in notes)
    questions = "\n".join("- linkId=%s (type %s): %s" % (i["linkId"], i["type"], i["text"]) for i in items)
    prompt = (
        "You extract facts from a patient's clinical documents to answer a prior authorization questionnaire.\n"
        "Rules:\n"
        "1. Answer only from the documents below. If a fact is not stated, set found=false.\n"
        "2. quote must be copied character-for-character from one document (one or two full sentences).\n"
        "3. doc_id must be the document the quote came from.\n"
        "4. value is the answer only: true/false for boolean, a number for integer/decimal.\n"
        "5. Do not decide whether policy criteria are met.\n\n"
        "Questions:\n" + questions + "\n\nDocuments:\n" + notes_block)
    sql = "SELECT AI_COMPLETE(model => '%s', prompt => ?, response_format => %s) AS r" % (model, _sql_literal({"type": "json", "schema": _SCHEMA}))
    raw = session.sql(sql, params=[prompt]).collect()[0][0]
    data = _json.loads(raw) if isinstance(raw, str) else raw
    types = {i["linkId"]: i["type"] for i in items}
    out = {}
    for a in (data or {}).get("answers", []):
        if not a.get("found") or a.get("linkId") not in types:
            continue
        value = _coerce(types[a["linkId"]], a.get("value"))
        if value is None:
            continue
        out[a["linkId"]] = {"value": value, "quote": a.get("quote"), "doc_id": a.get("doc_id"),
                            "confidence": a.get("confidence") or "Medium", "method": "cortex:" + model}
    return out, model



def run(session, patient_id, items, doc_ids):
    items = json.loads(items)
    doc_ids = json.loads(doc_ids)
    notes = q(session,
              "SELECT doc_id, title, TO_VARCHAR(encounter_date) AS encounter_date, text FROM CORE.CLINICAL_DOCUMENT "
              "WHERE patient_id = ? AND ARRAY_CONTAINS(doc_id::VARIANT, PARSE_JSON(?))",
              [patient_id, json.dumps(doc_ids)])
    found, model = cortex_extract(session, items, notes)
    texts = {n["doc_id"]: n["text"] for n in notes}
    answers = {k: v for k, v in found.items() if verify_quote(v.get("quote"), texts.get(v.get("doc_id")))}
    session.sql(
        "INSERT INTO AI.AI_RECOMMENDATION_AUDIT (pa_id, agent_name, model, output, recommendation, ai_assisted) "
        "SELECT NULL, 'DTR_AUTOFILL', ?, PARSE_JSON(?), NULL, TRUE",
        params=[model, json.dumps({"patient_id": patient_id, "answers": answers,
                                   "rejected": sorted(set(found) - set(answers))})]).collect()
    return {"answers": answers, "model": model}
$$;

